{
  "name": "zscore_margin_logsig",
  "intuition": "Use the normalized improvement signal (delta_z) as a signed margin: when the winner is much better than the loser, the loss pushes log_prob_w above log_prob_l with a larger margin; when the improvement is small, the update is gentle. Z-scoring stabilizes scales across instances so the same alpha works over different problem sizes and reward magnitudes.",
  "pseudocode": "Given pair (w,l) with log-probs lp_w, lp_l and improvement s=delta_z, define margin m = alpha * zscore(s). Loss = - E[ weight * logsigmoid( (lp_w - lp_l) - m ) ].",
  "hyperparams": {
    "paradigm_family": "pairwise_preference_margin",
    "signal_family": "delta_z",
    "link_family": "logsigmoid",
    "agg_family": "weighted_mean",
    "constraint_family": "nonneg_weight",
    "other_hparams": "alpha: margin scale; zscore over pairs to normalize delta_z"
  },
  "operators_used": ["logsigmoid", "zscore"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "delta_z"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = model_output[\"log_prob_w\"]\n    log_prob_l = model_output[\"log_prob_l\"]\n    weight = model_output[\"weight\"]\n    delta_z = model_output[\"delta_z\"]\n\n    alpha = float(extra.get(\"alpha\", extra.get(\"hyperparams\", {}).get(\"alpha\", 1.0)))\n\n    s = ops.zscore(delta_z)\n    margin = alpha * s\n    logits = (log_prob_w - log_prob_l) - margin\n    per_pair = -ops.logsigmoid(logits)\n\n    weighted = per_pair * weight\n    denom = ops.clamp(weight.sum(), min=1e-12)\n    return weighted.sum() / denom\n"
}

{
  "name": "loss_logsigmoid_001_cost_symm_swap_keysafe",
  "intuition": "Fix the static gate by being key-safe: accept either `log_prob_w`/`log_prob_l` or common aliases (`log_prob_win`/`log_prob_lose`, `logp_w`/`logp_l`). Also simplify the swap-symmetry: the averaged bidirectional logsigmoid loss is exactly `softplus(-x)` when the swapped logit is `-x`, so we compute a single stabilized `softplus(-x)` with clamping. Keep cost-gap detached and add finite/shape-safe clamping to avoid numerical blowups.",
  "pseudocode": "lpw = batch['log_prob_w'] if present else alias; lpl likewise; gap = (cost_b-cost_a).detach(); x = alpha*scale*(lpw-lpl) - beta*gap; x = clamp(x,-20,20); loss = softplus(-x); if weight: loss*=weight; return mean(loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_margin",
    "signal_family": "cost_gap",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "swap_symmetric"
  },
  "operators_used": [
    "softplus",
    "clamp"
  ],
  "code": "def generated_loss(batch, model_output, extra):
    # Key-safe retrieval for required log-prob inputs
    if 'log_prob_w' in batch:
        lpw = batch['log_prob_w']
    elif 'log_prob_win' in batch:
        lpw = batch['log_prob_win']
    elif 'logp_w' in batch:
        lpw = batch['logp_w']
    else:
        lpw = batch['log_prob_w']

    if 'log_prob_l' in batch:
        lpl = batch['log_prob_l']
    elif 'log_prob_lose' in batch:
        lpl = batch['log_prob_lose']
    elif 'logp_l' in batch:
        lpl = batch['logp_l']
    else:
        lpl = batch['log_prob_l']

    weight = batch.get('weight', None)

    hp = extra.get('hyperparams', {}) if extra is not None else {}
    alpha = float((extra.get('alpha', None) if extra is not None else None) or hp.get('alpha', 1.0))
    scale = float(hp.get('scale', 1.0))
    beta = float(hp.get('beta', 0.1))

    cost_a = batch.get('cost_a', None)
    cost_b = batch.get('cost_b', None)
    if cost_a is None or cost_b is None:
        gap = 0.0
    else:
        gap = (cost_b - cost_a).detach()

    x = alpha * scale * (lpw - lpl) - beta * gap
    x = ops.clamp(x, -20.0, 20.0)

    # swap-symmetric average of -logsigmoid(x) and -logsigmoid(-x) simplifies to softplus(-x)
    loss = ops.softplus(-x)

    if weight is not None:
        loss = loss * weight

    return loss.mean()",
  "theoretical_basis": ""
}
